-- ================================================================
-- TAMIL NADU LAND STACK - OFFICIAL LGD ADMINISTRATIVE SEED
-- Source: uploaded LGD Tamil Nadu District/Sub-District/Village files
-- State code: 33
-- Districts: 38
-- Sub-districts (Taluk-level): 317
-- Villages: 18681
-- ================================================================

-- IMPORTANT:
-- 1. LGD files do not contain latitude/longitude, so center_lat/center_lng
--    are left NULL for new records.
-- 2. LGD codes are used as the official administrative codes.
-- 3. Existing records with the same name are updated with the LGD code.
-- 4. This script does NOT create parcel/ULPIN records; those are a separate layer.

BEGIN;

-- Add LGD code columns if your existing schema does not have them.
ALTER TABLE public.districts ADD COLUMN IF NOT EXISTS lgd_code TEXT;
ALTER TABLE public.taluks ADD COLUMN IF NOT EXISTS lgd_code TEXT;

-- Create villages table if it does not already exist.
CREATE TABLE IF NOT EXISTS public.villages (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    taluk_id UUID NOT NULL REFERENCES public.taluks(id) ON DELETE CASCADE,
    name TEXT NOT NULL,
    code TEXT,
    center_lat DOUBLE PRECISION,
    center_lng DOUBLE PRECISION,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    UNIQUE (taluk_id, name)
);
ALTER TABLE public.villages ADD COLUMN IF NOT EXISTS code TEXT;

-- Helpful indexes
CREATE INDEX IF NOT EXISTS idx_districts_lgd_code ON public.districts(lgd_code);
CREATE INDEX IF NOT EXISTS idx_taluks_lgd_code ON public.taluks(lgd_code);
CREATE INDEX IF NOT EXISTS idx_villages_code ON public.villages(code);

